INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000059',NULL,1816,3,4,'diplomacy_international',5,'{"id":"NTL-E-000059","ad_day":4,"bs_day":null,"era_id":"shah_pre_rana","ad_year":1816,"bs_year":null,"ad_month":3,"bs_month":null,"category":"diplomacy_international","disputed":true,"title_en":"Treaty of Sugauli between Nepal and the East India Company","title_ne":"नेपाल र इस्ट इन्डिया कम्पनीबीच सुगौली सन्धि","importance":5,"summary_en":"Ending the Anglo-Nepalese War, the Treaty of Sugauli — drawn up in December 1815 and ratified on 4 March 1816 — made Nepal cede its conquests west of the Kali River, renounce claims to disputed Tarai lands, and accept a British Resident in Kathmandu.","summary_ne":"एङ्ग्लो–नेपाल युद्धको अन्त्य गर्दै सन् १८१५ डिसेम्बरमा तयार भई १८१६ मार्च ४ मा अनुमोदित सुगौली सन्धिले नेपाललाई काली नदीपश्चिमका विजित भूभाग छाड्न, विवादित तराईमाथिको दाबी त्याग्न र काठमाडौंमा ब्रिटिश रेजिडेन्ट स्वीकार गर्न बाध्य बनायो।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"1816-03-04","am":3,"ay":1816,"bs":"","id":"NTL-E-000059","adn":4,"era":"shah_pre_rana","sen":"Ending the Anglo-Nepalese War, the Treaty of Sugauli — drawn up in December 1815 and ratified on 4 March 1816 — made Nepal cede its conquests west of the Kali River, renounce claims to disputed Tarai lands, and accept a British Resident in Kathmandu.","sne":"एङ्ग्लो–नेपाल युद्धको अन्त्य गर्दै सन् १८१५ डिसेम्बरमा तयार भई १८१६ मार्च ४ मा अनुमोदित सुगौली सन्धिले नेपाललाई काली नदीपश्चिमका विजित भूभाग छाड्न, विवादित तराईमाथिको दाबी त्याग्न र काठमाडौंमा ब्रिटिश रेजिडेन्ट स्वीकार गर्न बाध्य बनायो।","ten":"Treaty of Sugauli between Nepal and the East India Company","tne":"नेपाल र इस्ट इन्डिया कम्पनीबीच सुगौली सन्धि","category":"diplomacy_international","disputed":true,"precision":"exact_day","confidence":0.89,"importance":5,"verification":"verified_multiple"},"ad_date_text":"1