INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000064',NULL,1924,NULL,NULL,'society',5,'{"id":"NTL-E-000064","ad_day":null,"bs_day":null,"era_id":"rana","ad_year":1924,"bs_year":null,"ad_month":null,"bs_month":null,"category":"society","disputed":true,"title_en":"Abolition of slavery in Nepal","title_ne":"नेपालमा दासप्रथा उन्मूलन","importance":5,"summary_en":"Following Prime Minister Chandra Shumsher''s 1924 initiative, slavery was abolished and some 57,889 slaves were emancipated by 1926, with owners compensated from a state fund; forms of bonded labour nevertheless persisted into the 21st century.","summary_ne":"प्रधानमन्त्री चन्द्रशमशेरको सन् १९२४ को पहलपछि दासप्रथा उन्मूलन गरियो र सन् १९२६ सम्म करिब ५७,८८९ दासदासी मुक्त गरिए; मालिकहरूलाई राज्यकोषबाट क्षतिपूर्ति दिइयो। तैपनि कमैया, कमलरीजस्ता बाँधा श्रमका रूप २१औँ शताब्दीसम्म कायम रहे।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"1924","ay":1924,"bs":"1980-09-17","id":"NTL-E-000064","era":"rana","sen":"Following Prime Minister Chandra Shumsher''s 1924 initiative, slavery was abolished and some 57,889 slaves were emancipated by 1926, with owners compensated from a state fund; forms of bonded labour nevertheless persisted into the 21st century.","sne":"प्रधानमन्त्री चन्द्रशमशेरको सन् १९२४ को पहलपछि दासप्रथा उन्मूलन गरियो र सन् १९२६ सम्म करिब ५७,८८९ दासदासी मुक्त गरिए; मालिकहरूलाई राज्यकोषबाट क्षतिपूर्ति दिइयो। तैपनि कमैया, कमलरीजस्ता बाँधा श्रमका रूप २१औँ शताब्दीसम्म कायम रहे।","ten":"Abolition of slavery in Nepal","tne":"नेपालमा दासप्रथा उन्मूलन","category":"society","disputed":true,"precision":"date_range","confidence":0.39,"importance":5,"verification":"disputed"},"ad_date_text":"1924","bs_date_text":"1980-09-17","source_build":"checkpoint04-published","date_precision":"date_range","confidence_score":0.39,"verification_status":"disputed","source_function_version":45}','2026-