INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000077',NULL,400,NULL,NULL,'politics_state',5,'{"id":"NTL-E-000077","ad_day":null,"bs_day":null,"era_id":"licchavi","ad_year":400,"bs_year":null,"ad_month":null,"bs_month":null,"category":"politics_state","disputed":true,"title_en":"Licchavi period","title_ne":"लिच्छवि काल","importance":5,"summary_en":"The Licchavi dynasty ruled the Kathmandu Valley from about the late fourth or fifth century until the eighth century CE, leaving the earliest continuous series of Sanskrit inscriptions and fostering trade and cultural links between South Asia and Tibet.","summary_ne":"चौथो शताब्दीको अन्त्य वा पाँचौँ शताब्दीदेखि आठौँ शताब्दीसम्म लिच्छवि वंशले काठमाडौं उपत्यकामा शासन गर्‍यो; यस कालका संस्कृत अभिलेखहरूको निरन्तर शृङ्खला सबैभन्दा पुरानो हो र यसले दक्षिण एसिया र तिब्बतबीच व्यापारिक तथा सांस्कृतिक सम्बन्ध बढायो।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"0400","ay":400,"bs":"","id":"NTL-E-000077","era":"licchavi","sen":"The Licchavi dynasty ruled the Kathmandu Valley from about the late fourth or fifth century until the eighth century CE, leaving the earliest continuous series of Sanskrit inscriptions and fostering trade and cultural links between South Asia and Tibet.","sne":"चौथो शताब्दीको अन्त्य वा पाँचौँ शताब्दीदेखि आठौँ शताब्दीसम्म लिच्छवि वंशले काठमाडौं उपत्यकामा शासन गर्‍यो; यस कालका संस्कृत अभिलेखहरूको निरन्तर शृङ्खला सबैभन्दा पुरानो हो र यसले दक्षिण एसिया र तिब्बतबीच व्यापारिक तथा सांस्कृतिक सम्बन्ध बढायो।","ten":"Licchavi period","tne":"लिच्छवि काल","category":"politics_state","disputed":true,"precision":"date_range","confidence":0.54,"importance":5,"verification":"approximate"},"ad_date_text":"0400","bs_date_text":"","source_build":"checkpoint04-published","date_precision":"date_range","confidence_score":0.54,"verification_status":"approximate","source_function_version":45}','2