INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000086',NULL,2026,8,26,'disaster_environment',5,'{"id":"NTL-E-000086","ad_day":26,"bs_day":10,"era_id":"federal_republic","ad_year":2026,"bs_year":2083,"ad_month":8,"bs_month":5,"category":"disaster_environment","disputed":true,"title_en":"Glacier collapse above the Lhende River triggers deadly floods in Rasuwa and Tibet","title_ne":"लेन्दे खोलामाथि हिमनदी खस्दा रसुवा र तिब्बतमा विनाशकारी बाढी","importance":5,"summary_en":"At about 08:37–08:40 Nepal time on 26 August 2026, a large section of glacier high above the Lhende River in Tibet collapsed, sending an ice-rock avalanche and flood down the Lhende, Bhotekoshi and Trishuli valleys in Rasuwa district. Hundreds of people were killed and more than a thousand were reported missing.","summary_ne":"सन् २०२६ अगस्ट २६ (वि.सं. २०८३ भदौ १०) बिहान करिब ८:३७–८:४० बजे तिब्बततर्फ लेन्दे खोलामाथिको हिमनदीको ठूलो भाग खस्दा हिउँ–चट्टानको पहिरो र बाढी रसुवाको लेन्दे, भोटेकोशी र त्रिशूली उपत्यकातर्फ बग्यो। सयौँ मानिसको मृत्यु भयो र हजारभन्दा बढी बेपत्ता भए।","mirrored_at":"2026-09-26T03:57:44.68977+00:00","raw_compact":{"ad":"2026-08-26","am":8,"ay":2026,"bd":10,"bm":5,"bs":"2083-05-10","by":2083,"id":"NTL-E-000086","adn":26,"era":"federal_republic","sen":"At about 08:37–08:40 Nepal time on 26 August 2026, a large section of glacier high above the Lhende River in Tibet collapsed, sending an ice-rock avalanche and flood down the Lhende, Bhotekoshi and Trishuli valleys in Rasuwa district. Hundreds of people were killed and more than a thousand were reported missing.","sne":"सन् २०२६ अगस्ट २६ (वि.सं. २०८३ भदौ १०) बिहान करिब ८:३७–८:४० बजे तिब्बततर्फ लेन्दे खोलामाथिको हिमनदीको ठूलो भाग खस्दा हिउँ–चट्टानको पहिरो र बाढी रसुवाको लेन्दे, भोटेकोशी र त्रिशूली उपत्यकातर्फ बग्यो। सयौँ मानिसको मृत्यु भयो र हजारभन्दा बढी बेपत्ता भए।","ten":"Glacier collapse above the Lhende River triggers