INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000162',NULL,1990,4,6,'politics_state',4,'{"id":"NTL-E-000162","ad_day":6,"bs_day":24,"era_id":"panchayat","ad_year":1990,"bs_year":2046,"ad_month":4,"bs_month":12,"category":"politics_state","disputed":true,"title_en":"Security forces fire on pro-democracy demonstrators outside the royal palace","title_ne":"राजदरबार अगाडि प्रजातन्त्रवादी प्रदर्शनकारीमाथि सुरक्षाकर्मीको गोली","importance":4,"summary_en":"On 6 April 1990 (Chaitra 24, 2046 BS) security forces opened fire on a huge crowd of demonstrators outside the royal palace in Kathmandu — the turning point of the People''s Movement. Estimates of the dead ranged from 50 to several hundred; two days later the king lifted the ban on political parties.","summary_ne":"वि.सं. २०४६ चैत २४ (सन् १९९० अप्रिल ६) मा काठमाडौंमा राजदरबार अगाडि जम्मा भएको ठूलो प्रदर्शनकारी भीडमाथि सुरक्षाकर्मीले गोली चलाए — यो जनआन्दोलनको निर्णायक मोड बन्यो। मृतकको अनुमान ५० देखि सयौँसम्म थियो; दुई दिनपछि राजाले राजनीतिक दलमाथिको प्रतिबन्ध हटाए।","mirrored_at":"2026-09-26T03:57:34.52307+00:00","raw_compact":{"ad":"1990-04-06","am":4,"ay":1990,"bd":24,"bm":12,"bs":"2046-12-24","by":2046,"id":"NTL-E-000162","adn":6,"era":"panchayat","sen":"On 6 April 1990 (Chaitra 24, 2046 BS) security forces opened fire on a huge crowd of demonstrators outside the royal palace in Kathmandu — the turning point of the People''s Movement. Estimates of the dead ranged from 50 to several hundred; two days later the king lifted the ban on political parties.","sne":"वि.सं. २०४६ चैत २४ (सन् १९९० अप्रिल ६) मा काठमाडौंमा राजदरबार अगाडि जम्मा भएको ठूलो प्रदर्शनकारी भीडमाथि सुरक्षाकर्मीले गोली चलाए — यो जनआन्दोलनको निर्णायक मोड बन्यो। मृतकको अनुमान ५० देखि सयौँसम्म थियो; दुई दिनपछि राजाले राजनीतिक दलमाथिको प्रतिबन्ध हटाए।","ten":"Security forces fire on pro-democracy demonstrators outside the royal palace","tne":"राज