INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000176',NULL,2023,1,15,'infrastructure_transport',3,'{"id":"NTL-E-000176","ad_day":15,"bs_day":1,"era_id":"federal_republic","ad_year":2023,"bs_year":2079,"ad_month":1,"bs_month":10,"category":"infrastructure_transport","disputed":false,"title_en":"Yeti Airlines Flight 691 crashes on approach to Pokhara, killing all 72 on board","title_ne":"पोखरा अवतरण गर्न लाग्दा यती एयरलाइन्सको उडान ६९१ दुर्घटनाग्रस्त, सवार सबै ७२ जनाको मृत्यु","importance":3,"summary_en":"On 15 January 2023 Yeti Airlines flight NYT691, an ATR 72, stalled and crashed into the Seti River gorge at Gharipatan while approaching the new Pokhara International Airport; all 72 people on board (68 passengers, 4 crew) died. The investigation found that both condition levers had been moved to the feathered position in flight.","summary_ne":"सन् २०२३ जनवरी १५ (वि.सं. २०७९ माघ १) मा यती एयरलाइन्सको एटीआर ७२ (उडान एनवाईटी६९१) नयाँ पोखरा अन्तर्राष्ट्रिय विमानस्थलमा अवतरण गर्न लाग्दा गतिहीन भई घारीपाटनमा सेती नदीको खोँचमा खस्यो; सवार सबै ७२ जना (६८ यात्रु र ४ चालक दल) को मृत्यु भयो। छानबिनले उडानका क्रममा दुवै कन्डिसन लिभर फेदर अवस्थामा सारिएको पत्ता लगायो।","mirrored_at":"2026-09-26T03:57:44.68977+00:00","raw_compact":{"ad":"2023-01-15","am":1,"ay":2023,"bd":1,"bm":10,"bs":"2079-10-01","by":2079,"id":"NTL-E-000176","adn":15,"era":"federal_republic","sen":"On 15 January 2023 Yeti Airlines flight NYT691, an ATR 72, stalled and crashed into the Seti River gorge at Gharipatan while approaching the new Pokhara International Airport; all 72 people on board (68 passengers, 4 crew) died. The investigation found that both condition levers had been moved to the feathered position in flight.","sne":"सन् २०२३ जनवरी १५ (वि.सं. २०७९ माघ १) मा यती एयरलाइन्सको एटीआर ७२ (उडान एनवाईटी६९१) नयाँ पोखरा अन्तर्राष्ट्रिय विमानस्थलमा अवतरण गर्न लाग्दा गतिहीन भई घारीपाटनमा सेती न