INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000187',NULL,1996,5,10,'disaster_environment',2,'{"id":"NTL-E-000187","ad_day":10,"bs_day":null,"era_id":"constitutional_monarchy","ad_year":1996,"bs_year":2053,"ad_month":5,"bs_month":1,"category":"disaster_environment","disputed":false,"title_en":"Storm on Everest kills eight climbers in a single day","title_ne":"सगरमाथामा आँधीले एकै दिन आठ आरोहीको ज्यान लियो","importance":2,"summary_en":"On the afternoon of 10 May 1996 a fast-developing blizzard overtook several commercial expeditions near the summit of Everest; eight climbers died in the storm and its aftermath (10–11 May), including the expedition leaders Rob Hall and Scott Fischer.","summary_ne":"सन् १९९६ मे १० (वि.सं. २०५३ वैशाख २८) को दिउँसो सगरमाथाको शिखरनजिक अचानक आएको हिमआँधीले धेरै व्यावसायिक अभियानलाई घेर्‍यो; आँधी र त्यसपछिका घटनामा (मे १०–११) अभियान नेता रब हल र स्कट फिसरसहित आठ आरोहीको मृत्यु भयो।","mirrored_at":"2026-09-26T03:57:38.84837+00:00","raw_compact":{"ad":"1996-05-10","am":5,"ay":1996,"bm":1,"bs":"2053-01-28","by":2053,"id":"NTL-E-000187","adn":10,"era":"constitutional_monarchy","sen":"On the afternoon of 10 May 1996 a fast-developing blizzard overtook several commercial expeditions near the summit of Everest; eight climbers died in the storm and its aftermath (10–11 May), including the expedition leaders Rob Hall and Scott Fischer.","sne":"सन् १९९६ मे १० (वि.सं. २०५३ वैशाख २८) को दिउँसो सगरमाथाको शिखरनजिक अचानक आएको हिमआँधीले धेरै व्यावसायिक अभियानलाई घेर्‍यो; आँधी र त्यसपछिका घटनामा (मे १०–११) अभियान नेता रब हल र स्कट फिसरसहित आठ आरोहीको मृत्यु भयो।","ten":"Storm on Everest kills eight climbers in a single day","tne":"सगरमाथामा आँधीले एकै दिन आठ आरोहीको ज्यान लियो","category":"disaster_environment","disputed":false,"precision":"date_range","confidence":0.89,"importance":2,"verification":"verified_multiple"},"ad_date_text":"1996-05-10","bs_date_text":"2053-01-28","source_build":"checkpoint04-published","date_precision":"date_range","confidence_score":0.89,"verification_status":"verified_multiple","source_function_version":45}','2026-09-26T03:57:38.84837+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000188',NULL,2014,4,18,'disaster_environment',3,'{"id":"NTL-E-000188","ad_day":18,"bs_day":5,"era_id":"republic_transition","ad_year":2014,"bs_year":2071,"ad_month":4,"bs_month":1,"category":"disaster_environment","disputed":true,"title_en":"Khumbu Icefall avalanche kills 16 mountain workers on Everest","title_ne":"खुम्बु हिमपहिरोमा सगरमाथाका १६ पर्वतीय कामदारको मृत्यु","importance":3,"summary_en":"On 18 April 2014 a serac collapse on Everest''s west shoulder sent an avalanche into the Khumbu Icefall below Camp 1, killing 16 high-altitude workers, 13 of them Sherpas — at the time the deadliest single day on the mountain. The spring climbing season from the Nepal side was effectively cancelled.","summary_ne":"सन् २०१४ अप्रिल १८ (वि.सं. २०७१ वैशाख ५) मा सगरमाथाको पश्चिमी काँधबाट हिउँको चट्टान खसेर शिविर १ मुनिको खुम्बु आइसफलमा हिमपहिरो गयो; १३ शेर्पासहित १६ उच्च हिमाली कामदारको मृत्यु भयो — त्यतिबेलासम्म यो सगरमाथाकै सबैभन्दा घातक दिन थियो। नेपालतर्फको वसन्त आरोहण सिजन व्यवहारतः रद्द भयो।","mirrored_at":"2026-09-26T03:57:41.372373+00:00","raw_compact":{"ad":"2014-04-18","am":4,"ay":2014,"bd":5,"bm":1,"bs":"2071-01-05","by":2071,"id":"NTL-E-000188","adn":18,"era":"republic_transition","sen":"On 18 April 2014 a serac collapse on Everest''s west shoulder sent an avalanche into the Khumbu Icefall below Camp 1, killing 16 high-altitude workers, 13 of them Sherpas — at the time the deadliest single day on the mountain. The spring climbing season from the Nepal side was effectively cancelled.","sne":"सन् २०१४ अप्रिल १८ (वि.सं. २०७१ वैशाख ५) मा सगरमाथाको पश्चिमी काँधबाट हिउँको चट्टान खसेर शिविर १ मुनिको खुम्बु आइसफलमा हिमपहिरो गयो; १३ शेर्पासहित १६ उच्च हिमाली कामदारको मृत्यु भयो — त्यतिबेलासम्म यो सगरमाथाकै सबैभन्दा घातक दिन थियो। नेपालतर्फको वसन्त आरोहण सिजन व्यवहारतः रद्द भयो।","ten":"Khumbu Icefall avalanche kills