INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000216',NULL,-23049,NULL,NULL,'archaeology_epigraphy',4,'{"id":"NTL-E-000216","ad_day":null,"bs_day":null,"era_id":"early_traditions","ad_year":-23049,"bs_year":null,"ad_month":null,"bs_month":null,"category":"archaeology_epigraphy","disputed":true,"title_en":"Stone-tool makers in the Siwalik valleys of western Nepal (Late Pleistocene)","title_ne":"पश्चिम नेपालका शिवालिक उपत्यकामा ढुङ्गे औजार बनाउने मानिस (उत्तर प्लाइस्टोसिन)","importance":4,"summary_en":"Archaeological surveys in the Dang–Deukhuri valleys and at the Satpati handaxe site (Nawalparasi) show that people making stone tools lived in the Siwalik foothills of Nepal in the Late Pleistocene; a synthesis dates comparable Nepali industries back to about 25,000 years ago, and a Middle Palaeolithic site there may be older still.","summary_ne":"दाङ–देउखुरी उपत्यका र सतपाटीको हाते बञ्चरो भेटिएको स्थलमा गरिएका पुरातात्त्विक सर्वेक्षणले उत्तर प्लाइस्टोसिन कालमा नेपालको शिवालिक भेगमा ढुङ्गे औजार बनाउने मानिस बस्थे भन्ने देखाउँछन्; एउटा अध्ययनले यस्ता नेपाली औजार-परम्परा करिब २५ हजार वर्ष पुराना भएको र त्यहाँको एउटा मध्य पुरापाषाणकालीन स्थल अझ पुरानो हुन सक्ने बताएको छ।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"-23049","ay":-23049,"bs":"","id":"NTL-E-000216","era":"early_traditions","sen":"Archaeological surveys in the Dang–Deukhuri valleys and at the Satpati handaxe site (Nawalparasi) show that people making stone tools lived in the Siwalik foothills of Nepal in the Late Pleistocene; a synthesis dates comparable Nepali industries back to about 25,000 years ago, and a Middle Palaeolithic site there may be older still.","sne":"दाङ–देउखुरी उपत्यका र सतपाटीको हाते बञ्चरो भेटिएको स्थलमा गरिएका पुरातात्त्विक सर्वेक्षणले उत्तर प्लाइस्टोसिन कालमा नेपालको शिवालिक भेगमा ढुङ्गे औजार बनाउने मानिस बस्थे भन्ने देखाउँछन्; एउटा अध्ययनले यस्ता नेपाली औजार-परम्परा करिब २५ हजार वर्ष पुराना भएको र त्यहाँको एउटा मध्य पुरापाषाणकालीन स्थल अझ पुरानो हुन सक्ने बताएको छ।","ten":"Stone-tool makers in the Siwalik valleys of western Nepal (Late Pleistocene)","tne":"पश्चिम नेपालका शिवालिक उपत्यकामा ढुङ्गे औजार बनाउने मानिस (उत्तर प्लाइस्टोसिन)","category":"archaeology_epigraphy","disputed":true,"precision":"circa","confidence":0.84,"importance":4,"verification":"verified_scholarly"},"ad_date_text":"-23049","bs_date_text":"","source_build":"checkpoint04-published","date_precision":"circa","confidence_score":0.84,"verification_status":"verified_scholarly","source_function_version":45}','2026-09-26T03:57:25.857064+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000217',NULL,1896,12,1,'archaeology_epigraphy',4,'{"id":"NTL-E-000217","ad_day":1,"bs_day":null,"era_id":"rana","ad_year":1896,"bs_year":null,"ad_month":12,"bs_month":null,"category":"archaeology_epigraphy","disputed":false,"title_en":"Ashoka''s pillar at Lumbini rediscovered","title_ne":"लुम्बिनीमा अशोक स्तम्भको पुनः खोज","importance":4,"summary_en":"On 1 December 1896, during an excavation led by General Khadga Shumsher Rana, governor of Palpa, and the archaeologist A. A. Führer, the pillar erected by Emperor Ashoka at Lumbini — lost in the undergrowth for centuries — was uncovered; its Brahmi inscription identifies the site as the Buddha''s birthplace.","summary_ne":"सन् १८९६ डिसेम्बर १ मा पाल्पाका गभर्नर जनरल खड्गशमशेर राणा र पुरातत्त्वविद् ए. ए. फ्युरेरको नेतृत्वमा भएको उत्खननमा शताब्दियौँदेखि झाडीमा हराएको सम्राट अशोकको लुम्बिनी स्तम्भ फेला पर्‍यो; यसको ब्राह्मी अभिलेखले यो स्थान बुद्धको जन्मस्थल भएको पुष्टि गर्छ।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"1896-12-01","am":12,"ay":1896,"bs":"","id":"NTL-E-000217","adn":1,"era":"rana","sen":"On 1 December 1896, during an excavation led by General Khadga Shumsher Rana, governor of Palpa, and the archaeologist A. A. Führer, the pillar erected by Emperor Ashoka at Lumbini — lost in the undergrowth for centuries — was uncovered; its Brahmi inscription identifies the site as the Buddha''s birthplace.","sne":"सन् १८९६ डिसेम्बर १ मा पाल्पाका गभर्नर जनरल खड्गशमशेर राणा र पुरातत्त्वविद् ए. ए. फ्युरेरको नेतृत्वमा भएको उत्खननमा शताब्दियौँदेखि झाडीमा हराएको सम्राट अशोकको लुम्बिनी स्तम्भ फेला पर्‍यो; यसको ब्राह्मी अभिलेखले यो स्थान बुद्धको जन्मस्थल भएको पुष्टि गर्छ।","ten":"Ashoka''s pillar at Lumbini rediscovered","tne":"लुम्बिनीमा अशोक स्तम्भको पुनः खोज","category":"archaeology_epigraphy","disputed":false,"precision":"exact_day","confidence":0.95,"importance":4,"verification":"verified_multiple"},"ad_date_text":"1896-12-01","bs_date_text":"","source_build":"checkpoint04-published","date_precision":"exact_day","confidence_score":0.95,"verification_status":"verified_multiple","source_function_version":45}','2026-09-26T03:57:25.857064+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000218',NULL,1312,NULL,NULL,'archaeology_epigraphy',3,'{"id":"NTL-E-000218","ad_day":null,"bs_day":null,"era_id":"malla","ad_year":1312,"bs_year":null,"ad_month":null,"bs_month":null,"category":"archaeology_epigraphy","disputed":true,"title_en":"King Ripu Malla of western Nepal adds his inscription to the Lumbini pillar","title_ne":"पश्चिम नेपालका राजा रिपु मल्लद्वारा लुम्बिनी स्तम्भमा अभिलेख","importance":3,"summary_en":"In 1312 CE Ripu Malla, a king of western Nepal, paid homage at Lumbini and had the words \"Om Mani Padme Hum Ripu Malla Chiran Jayatu\" engraved on Ashoka''s pillar; according to the Lumbini Development Trust the pillar was afterwards lost in the undergrowth until 1896.","summary_ne":"सन् १३१२ मा पश्चिम नेपालका राजा रिपु मल्लले लुम्बिनीमा पूजा गरी अशोक स्तम्भमा \"ओं मणि पद्मे हुं रिपु मल्ल चिरं जयतु\" भन्ने शब्द कुँदाए; लुम्बिनी विकास कोषअनुसार त्यसपछि स्तम्भ सन् १८९६ सम्म झाडीमा हराएको थियो।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"1312","ay":1312,"bs":"","id":"NTL-E-000218","era":"malla","sen":"In 1312 CE Ripu Malla, a king of western Nepal, paid homage at Lumbini and had the words \"Om Mani Padme Hum Ripu Malla Chiran Jayatu\" engraved on Ashoka''s pillar; according to the Lumbini Development Trust the pillar was afterwards lost in the undergrowth until 1896.","sne":"सन् १३१२ मा पश्चिम नेपालका राजा रिपु मल्लले लुम्बिनीमा पूजा गरी अशोक स्तम्भमा \"ओं मणि पद्मे हुं रिपु मल्ल चिरं जयतु\" भन्ने शब्द कुँदाए; लुम्बिनी विकास कोषअनुसार त्यसपछि स्तम्भ सन् १८९६ सम्म झाडीमा हराएको थियो।","ten":"King Ripu Malla of western Nepal adds his inscription to the Lumbini pillar","tne":"पश्चिम नेपालका राजा रिपु मल्लद्वारा लुम्बिनी स्तम्भमा अभिलेख","category":"archaeology_epigraphy","disputed":true,"precision":"year","confidence":0.6,"importance":3,"verification":"probable"},"ad_date_text":"1312","bs_date_text":"","source_build":"checkpoint04-published","date_precision":"year","confidence_score":0.6,"verification_status":"probable","source_function_version":45}','2026-09-26T03:57:25.857064+00:00');
