INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000220',NULL,1382,NULL,NULL,'arts_literature_language',3,'{"id":"NTL-E-000220","ad_day":null,"bs_day":null,"era_id":"malla","ad_year":1382,"bs_year":null,"ad_month":null,"bs_month":null,"category":"arts_literature_language","disputed":true,"title_en":"The Gopalarajavamsavali, the oldest surviving chronicle of the Kathmandu Valley, is compiled","title_ne":"काठमाडौं उपत्यकाको सबैभन्दा पुरानो उपलब्ध वंशावली गोपालराजवंशावलीको रचना","importance":3,"summary_en":"The Gopalarajavamsavali, a chronicle listing the rulers of the Kathmandu Valley from legendary times, ends its chronology in the reign of Jayasthiti Malla (fl. 1382–1395), which places its compilation in the late fourteenth century.","summary_ne":"काठमाडौं उपत्यकाका शासकहरूको पौराणिक कालदेखिको सूची दिने गोपालराजवंशावलीको कालक्रम जयस्थिति मल्ल (शासनकाल करिब सन् १३८२–१३९५) को पालामा टुङ्गिन्छ; त्यसैले यसको रचना चौधौँ शताब्दीको अन्त्यतिर भएको मानिन्छ।","mirrored_at":"2026-09-26T03:57:25.857064+00:00","raw_compact":{"ad":"1382","ay":1382,"bs":"","id":"NTL-E-000220","era":"malla","sen":"The Gopalarajavamsavali, a chronicle listing the rulers of the Kathmandu Valley from legendary times, ends its chronology in the reign of Jayasthiti Malla (fl. 1382–1395), which places its compilation in the late fourteenth century.","sne":"काठमाडौं उपत्यकाका शासकहरूको पौराणिक कालदेखिको सूची दिने गोपालराजवंशावलीको कालक्रम जयस्थिति मल्ल (शासनकाल करिब सन् १३८२–१३९५) को पालामा टुङ्गिन्छ; त्यसैले यसको रचना चौधौँ शताब्दीको अन्त्यतिर भएको मानिन्छ।","ten":"The Gopalarajavamsavali, the oldest surviving chronicle of the Kathmandu Valley, is compiled","tne":"काठमाडौं उपत्यकाको सबैभन्दा पुरानो उपलब्ध वंशावली गोपालराजवंशावलीको रचना","category":"arts_literature_language","disputed":true,"precision":"date_range","confidence":0.5,"importance":3,"verification":"approximate"},"ad_date_text":"138