INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000222',NULL,2008,10,23,'religion_culture',4,'{"id":"NTL-E-000222","ad_day":23,"bs_day":7,"era_id":"republic_transition","ad_year":2008,"bs_year":2065,"ad_month":10,"bs_month":7,"category":"religion_culture","disputed":true,"title_en":"Government recognises Nepal Sambat as a national calendar era","title_ne":"सरकारद्वारा नेपाल सम्बतलाई राष्ट्रिय सम्बतका रूपमा मान्यता","importance":4,"summary_en":"On 23 October 2008 (Kartik 7, 2065 BS) the government officially recognised Nepal Sambat, the lunar era begun in 879 CE; Prime Minister Pushpa Kamal Dahal later described it as a decision of the first republican government, which he led.","summary_ne":"सन् २००८ अक्टोबर २३ (वि.सं. २०६५ कात्तिक ७) मा सरकारले सन् ८७९ मा सुरु भएको चान्द्र सम्बत, नेपाल सम्बतलाई आधिकारिक मान्यता दियो; पछि प्रधानमन्त्री पुष्पकमल दाहालले यसलाई आफ्नै नेतृत्वको पहिलो गणतान्त्रिक सरकारको निर्णय भनेका थिए।","mirrored_at":"2026-09-26T03:57:41.372373+00:00","raw_compact":{"ad":"2008-10-23","am":10,"ay":2008,"bd":7,"bm":7,"bs":"2065-07-07","by":2065,"id":"NTL-E-000222","adn":23,"era":"republic_transition","sen":"On 23 October 2008 (Kartik 7, 2065 BS) the government officially recognised Nepal Sambat, the lunar era begun in 879 CE; Prime Minister Pushpa Kamal Dahal later described it as a decision of the first republican government, which he led.","sne":"सन् २००८ अक्टोबर २३ (वि.सं. २०६५ कात्तिक ७) मा सरकारले सन् ८७९ मा सुरु भएको चान्द्र सम्बत, नेपाल सम्बतलाई आधिकारिक मान्यता दियो; पछि प्रधानमन्त्री पुष्पकमल दाहालले यसलाई आफ्नै नेतृत्वको पहिलो गणतान्त्रिक सरकारको निर्णय भनेका थिए।","ten":"Government recognises Nepal Sambat as a national calendar era","tne":"सरकारद्वारा नेपाल सम्बतलाई राष्ट्रिय सम्बतका रूपमा मान्यता","category":"religion_culture","disputed":true,"precision":"exact_day","confidence":0.54,"importance":4,"verification":"probable"},"ad_d