INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000224',NULL,2023,11,13,'religion_culture',3,'{"id":"NTL-E-000224","ad_day":13,"bs_day":27,"era_id":"federal_republic","ad_year":2023,"bs_year":2080,"ad_month":11,"bs_month":7,"category":"religion_culture","disputed":true,"title_en":"Cabinet decides to use Nepal Sambat in all government documents","title_ne":"सबै सरकारी कागजातमा नेपाल सम्बत प्रयोग गर्ने मन्त्रिपरिषद्को निर्णय","importance":3,"summary_en":"On 13 November 2023 (Kartik 27, 2080 BS) the Council of Ministers decided to bring Nepal Sambat into use in all government documents and work, as announced by Prime Minister Pushpa Kamal Dahal the next day at the Nepal Sambat 1144 New Year programme.","summary_ne":"सन् २०२३ नोभेम्बर १३ (वि.सं. २०८० कात्तिक २७) मा मन्त्रिपरिषद्ले सबै सरकारी कागजात र काममा नेपाल सम्बत प्रयोगमा ल्याउने निर्णय गर्‍यो; भोलिपल्ट नेपाल सम्बत ११४४ को नयाँ वर्ष कार्यक्रममा प्रधानमन्त्री पुष्पकमल दाहालले यसको जानकारी दिए।","mirrored_at":"2026-09-26T03:57:44.68977+00:00","raw_compact":{"ad":"2023-11-13","am":11,"ay":2023,"bd":27,"bm":7,"bs":"2080-07-27","by":2080,"id":"NTL-E-000224","adn":13,"era":"federal_republic","sen":"On 13 November 2023 (Kartik 27, 2080 BS) the Council of Ministers decided to bring Nepal Sambat into use in all government documents and work, as announced by Prime Minister Pushpa Kamal Dahal the next day at the Nepal Sambat 1144 New Year programme.","sne":"सन् २०२३ नोभेम्बर १३ (वि.सं. २०८० कात्तिक २७) मा मन्त्रिपरिषद्ले सबै सरकारी कागजात र काममा नेपाल सम्बत प्रयोगमा ल्याउने निर्णय गर्‍यो; भोलिपल्ट नेपाल सम्बत ११४४ को नयाँ वर्ष कार्यक्रममा प्रधानमन्त्री पुष्पकमल दाहालले यसको जानकारी दिए।","ten":"Cabinet decides to use Nepal Sambat in all government documents","tne":"सबै सरकारी कागजातमा नेपाल सम्बत प्रयोग गर्ने मन्त्रिपरिषद्को निर्णय","category":"religion_culture","disputed":true,"precision":"exact_day","confidence"