INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000226',NULL,2020,6,13,'politics_state',4,'{"id":"NTL-E-000226","ad_day":13,"bs_day":31,"era_id":"federal_republic","ad_year":2020,"bs_year":2077,"ad_month":6,"bs_month":2,"category":"politics_state","disputed":false,"title_en":"House of Representatives unanimously passes amendment putting Nepal''s updated map in the coat of arms","title_ne":"नेपालको अद्यावधिक नक्सा निशान छापमा राख्ने संविधान संशोधन प्रतिनिधि सभाबाट सर्वसम्मत पारित","importance":4,"summary_en":"On 13 June 2020 (Jestha 31, 2077 BS) all 258 members present in the House of Representatives voted for the Second Amendment bill, which replaces the map in the national coat of arms with an updated map including Limpiyadhura, Lipulekh and Kalapani.","summary_ne":"सन् २०२० जुन १३ (वि.सं. २०७७ जेठ ३१) मा प्रतिनिधि सभामा उपस्थित सबै २५८ सदस्यले निशान छापको नक्सालाई लिम्पियाधुरा, लिपुलेक र कालापानी समेटिएको अद्यावधिक नक्साले प्रतिस्थापन गर्ने संविधानको दोस्रो संशोधन विधेयकको पक्षमा मत दिए।","mirrored_at":"2026-09-26T03:57:44.68977+00:00","raw_compact":{"ad":"2020-06-13","am":6,"ay":2020,"bd":31,"bm":2,"bs":"2077-02-31","by":2077,"id":"NTL-E-000226","adn":13,"era":"federal_republic","sen":"On 13 June 2020 (Jestha 31, 2077 BS) all 258 members present in the House of Representatives voted for the Second Amendment bill, which replaces the map in the national coat of arms with an updated map including Limpiyadhura, Lipulekh and Kalapani.","sne":"सन् २०२० जुन १३ (वि.सं. २०७७ जेठ ३१) मा प्रतिनिधि सभामा उपस्थित सबै २५८ सदस्यले निशान छापको नक्सालाई लिम्पियाधुरा, लिपुलेक र कालापानी समेटिएको अद्यावधिक नक्साले प्रतिस्थापन गर्ने संविधानको दोस्रो संशोधन विधेयकको पक्षमा मत दिए।","ten":"House of Representatives unanimously passes amendment putting Nepal''s updated map in the coat of arms","tne":"नेपालको अद्यावधिक नक्सा निशान छापमा राख्ने संविधान संशोधन प्रतिनिधि सभाबाट सर्वसम्मत पारित","category":"politics_state","disputed":false,"precision":"exact_day","confidence":0.89,"importance":4,"verification":"verified_multiple"},"ad_date_text":"2020-06-13","bs_date_text":"2077-02-31","source_build":"checkpoint04-published","date_precision":"exact_day","confidence_score":0.89,"verification_status":"verified_multiple","source_function_version":45}','2026-09-26T03:57:44.68977+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000227',NULL,2020,6,18,'politics_state',4,'{"id":"NTL-E-000227","ad_day":18,"bs_day":4,"era_id":"federal_republic","ad_year":2020,"bs_year":2077,"ad_month":6,"bs_month":3,"category":"politics_state","disputed":false,"title_en":"Second Amendment authenticated — updated map enters the national coat of arms","title_ne":"दोस्रो संविधान संशोधन प्रमाणीकरण — अद्यावधिक नक्सा निशान छापमा","importance":4,"summary_en":"On 18 June 2020 (Asar 4, 2077 BS) the National Assembly passed the Second Amendment unanimously (57 votes) and President Bidya Devi Bhandari authenticated it the same evening, placing the updated map including Limpiyadhura, Lipulekh and Kalapani in Nepal''s coat of arms. India''s foreign ministry called the enlarged claims untenable.","summary_ne":"सन् २०२० जुन १८ (वि.सं. २०७७ असार ४) मा राष्ट्रिय सभाले दोस्रो संविधान संशोधन सर्वसम्मत (५७ मत) पारित गर्‍यो र सोही साँझ राष्ट्रपति विद्यादेवी भण्डारीले प्रमाणीकरण गरिन्; यसले लिम्पियाधुरा, लिपुलेक र कालापानी समेटिएको अद्यावधिक नक्सा नेपालको निशान छापमा राख्यो। भारतको विदेश मन्त्रालयले यो दाबी टिक्ने खालको नभएको प्रतिक्रिया दियो।","mirrored_at":"2026-09-26T03:57:44.68977+00:00","raw_compact":{"ad":"2020-06-18","am":6,"ay":2020,"bd":4,"bm":3,"bs":"2077-03-04","by":2077,"id":"NTL-E-000227","adn":18,"era":"federal_republic","sen":"On 18 June 2020 (Asar 4, 2077 BS) the National Assembly passed the Second Amendment unanimously (57 votes) and President Bidya Devi Bhandari authenticated it the same evening, placing the updated map including Limpiyadhura, Lipulekh and Kalapani in Nepal''s coat of arms. India''s foreign ministry called the enlarged claims untenable.","sne":"सन् २०२० जुन १८ (वि.सं. २०७७ असार ४) मा राष्ट्रिय सभाले दोस्रो संविधान संशोधन सर्वसम्मत (५७ मत) पारित गर्‍यो र सोही साँझ राष्ट्रपति विद्यादेवी भण्डारीले प्रमाणीकरण गरिन्; यसले लिम्पियाधुरा, लिपुलेक र कालापानी समेटिएको अद्यावधिक नक्सा नेपालको निशान छापमा राख्यो। भारतको विदेश मन्त्रालयले यो दाबी टिक्ने खालको नभएको प्रतिक्रिया दियो।","ten":"Second Amendment authenticated — updated map enters the national coat of arms","tne":"दोस्रो संविधान संशोधन प्रमाणीकरण — अद्यावधिक नक्सा निशान छापमा","category":"politics_state","disputed":false,"precision":"exact_day","confidence":0.89,"importance":4,"verification":"verified_multiple"},"ad_date_text":"2020-06-18","bs_date_text":"2077-03-04","source_build":"checkpoint04-published","date_precision":"exact_day","confidence_score":0.89,"verification_status":"verified_multiple","source_function_version":45}','2026-09-26T03:57:44.68977+00:00');
