INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000230',NULL,2011,5,24,'law_justice_rights',4,'{"id":"NTL-E-000230","ad_day":24,"bs_day":10,"era_id":"republic_transition","ad_year":2011,"bs_year":2068,"ad_month":5,"bs_month":2,"category":"law_justice_rights","disputed":true,"title_en":"Parliament passes the Caste-based Discrimination and Untouchability Act","title_ne":"जातीय भेदभाव तथा छुवाछुत (कसुर र सजाय) ऐन संसद्बाट पारित","importance":4,"summary_en":"On 24 May 2011 (Jestha 10, 2068 BS) the Legislature-Parliament passed the Caste-based Discrimination and Untouchability (Offence and Punishment) Act, 2068, which makes untouchability and caste discrimination criminal offences and provides compensation for victims; the bill had been before parliament for two years.","summary_ne":"सन् २०११ मे २४ (वि.सं. २०६८ जेठ १०) मा व्यवस्थापिका–संसद्ले जातीय भेदभाव तथा छुवाछुत (कसुर र सजाय) ऐन, २०६८ पारित गर्‍यो; यसले छुवाछुत र जातीय भेदभावलाई फौजदारी कसुर बनाउँछ र पीडितलाई क्षतिपूर्तिको व्यवस्था गर्छ। विधेयक दुई वर्षदेखि संसद्मा विचाराधीन थियो।","mirrored_at":"2026-09-26T03:57:41.372373+00:00","raw_compact":{"ad":"2011-05-24","am":5,"ay":2011,"bd":10,"bm":2,"bs":"2068-02-10","by":2068,"id":"NTL-E-000230","adn":24,"era":"republic_transition","sen":"On 24 May 2011 (Jestha 10, 2068 BS) the Legislature-Parliament passed the Caste-based Discrimination and Untouchability (Offence and Punishment) Act, 2068, which makes untouchability and caste discrimination criminal offences and provides compensation for victims; the bill had been before parliament for two years.","sne":"सन् २०११ मे २४ (वि.सं. २०६८ जेठ १०) मा व्यवस्थापिका–संसद्ले जातीय भेदभाव तथा छुवाछुत (कसुर र सजाय) ऐन, २०६८ पारित गर्‍यो; यसले छुवाछुत र जातीय भेदभावलाई फौजदारी कसुर बनाउँछ र पीडितलाई क्षतिपूर्तिको व्यवस्था गर्छ। विधेयक दुई वर्षदेखि संसद्मा विचाराधीन थियो।","ten":"Parliament passes the Caste-based Discrimination and Untouchability Act","tne":"जातीय भेदभाव तथा छुवाछुत (कसुर र सजाय) ऐन संसद्बाट पारित","category":"law_justice_rights","disputed":true,"precision":"exact_day","confidence":0.54,"importance":4,"verification":"probable"},"ad_date_text":"2011-05-24","bs_date_text":"2068-02-10","source_build":"checkpoint04-published","date_precision":"exact_day","confidence_score":0.54,"verification_status":"probable","source_function_version":45}','2026-09-26T03:57:41.372373+00:00');
INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000231',NULL,2007,1,16,'society',4,'{"id":"NTL-E-000231","ad_day":16,"bs_day":2,"era_id":"constitutional_monarchy","ad_year":2007,"bs_year":2063,"ad_month":1,"bs_month":10,"category":"society","disputed":true,"title_en":"Madhesh uprising of 2007 begins","title_ne":"२०६३ सालको मधेस आन्दोलन सुरु","importance":4,"summary_en":"In January 2007, after Madhesi activists burned copies of the newly promulgated Interim Constitution on 16 January, protests for Madhesi identity, representation and federalism spread across the Tarai; the killing of the youth Ramesh Mahato in Lahan on 19 January intensified the movement, which brought state restructuring and federalism to the centre of national politics.","summary_ne":"सन् २००७ जनवरीमा नयाँ जारी अन्तरिम संविधानको प्रति मधेसी अभियन्ताले जनवरी १६ (वि.सं. २०६३ माघ २) मा जलाएपछि मधेसी पहिचान, प्रतिनिधित्व र सङ्घीयताका माग राख्दै आन्दोलन तराईभर फैलियो; जनवरी १९ (माघ ५) मा लहानमा किशोर रमेश महतो मारिएपछि आन्दोलन चर्कियो, जसले राज्य पुनर्संरचना र सङ्घीयतालाई राष्ट्रिय राजनीतिको केन्द्रमा ल्यायो।","mirrored_at":"2026-09-26T03:57:41.372373+00:00","raw_compact":{"ad":"2007-01-16","am":1,"ay":2007,"bd":2,"bm":10,"bs":"2063-10-02","by":2063,"id":"NTL-E-000231","adn":16,"era":"constitutional_monarchy","sen":"In January 2007, after Madhesi activists burned copies of the newly promulgated Interim Constitution on 16 January, protests for Madhesi identity, representation and federalism spread across the Tarai; the killing of the youth Ramesh Mahato in Lahan on 19 January intensified the movement, which brought state restructuring and federalism to the centre of national politics.","sne":"सन् २००७ जनवरीमा नयाँ जारी अन्तरिम संविधानको प्रति मधेसी अभियन्ताले जनवरी १६ (वि.सं. २०६३ माघ २) मा जलाएपछि मधेसी पहिचान, प्रतिनिधित्व र सङ्घीयताका माग राख्दै आन्दोलन तराईभर फैलियो; जनवरी १९ (माघ ५) मा लहानमा किशोर रमेश महतो मारिएपछि आन्दोलन चर्कियो, जसले राज्य पुनर्संरचना र सङ्घीयतालाई राष्ट्रिय राजनीतिको केन्द्रमा ल्यायो।","ten":"Madhesh uprising of 2007 begins","tne":"२०६३ सालको मधेस आन्दोलन सुरु","category":"society","disputed":true,"precision":"exact_day","confidence":0.89,"importance":4,"verification":"verified_multiple"},"ad_date_text":"2007-01-16","bs_date_text":"2063-10-02","source_build":"checkpoint04-published","date_precision":"exact_day","confidence_score":0.89,"verification_status":"verified_multiple","source_function_version":45}','2026-09-26T03:57:41.372373+00:00');
