INSERT OR REPLACE INTO content_records(table_name,record_key,ad_date,year,month,day,category,sort_order,payload,updated_at) VALUES('time_machine_moments','NTL-E-000600',NULL,1976,12,26,'politics_state',3,'{"id":"NTL-E-000600","ad_day":26,"bs_day":null,"era_id":"panchayat","ad_year":1976,"bs_year":null,"ad_month":12,"bs_month":null,"category":"politics_state","disputed":true,"title_en":"Communist Party of Nepal (Marxist–Leninist) founded","title_ne":"नेकपा (मार्क्सवादी–लेनिनवादी) को स्थापना","importance":3,"summary_en":"Between 26 December 1976 and 26 December 1978, the Communist Party of Nepal (Marxist–Leninist), which grew out of the Jhapa movement and counted K. P. Sharma Oli, Madan Bhandari and Madhav Kumar Nepal among its leaders, was formally established on 26 December; two timelines from the same outlet give the year as 1976 and 1978.","summary_ne":"सन् १९७६ डिसेम्बर २६ देखि सन् १९७८ डिसेम्बर २६ सम्म झापा आन्दोलनबाट विकसित भएको र केपी शर्मा ओली, मदन भण्डारी तथा माधवकुमार नेपाललाई नेताका रूपमा गनिने नेकपा (माले) डिसेम्बर २६ मा औपचारिक रूपमा स्थापना भयो; एउटै सञ्चारमाध्यमका दुई समयरेखाले वर्ष सन् १९७६ र १९७८ दिएका छन्।","mirrored_at":"2026-09-26T03:57:31.869761+00:00","raw_compact":{"ad":"1976-12-26","am":12,"ay":1976,"bs":"2033-09-12","id":"NTL-E-000600","adn":26,"era":"panchayat","sen":"Between 26 December 1976 and 26 December 1978, the Communist Party of Nepal (Marxist–Leninist), which grew out of the Jhapa movement and counted K. P. Sharma Oli, Madan Bhandari and Madhav Kumar Nepal among its leaders, was formally established on 26 December; two timelines from the same outlet give the year as 1976 and 1978.","sne":"सन् १९७६ डिसेम्बर २६ देखि सन् १९७८ डिसेम्बर २६ सम्म झापा आन्दोलनबाट विकसित भएको र केपी शर्मा ओली, मदन भण्डारी तथा माधवकुमार नेपाललाई नेताका रूपमा गनिने नेकपा (माले) डिसेम्बर २६ मा औपचारिक रूपमा स्थापना भयो; एउटै सञ्चारमाध्यमका दुई समयरेखाले वर्ष सन् १९७६ र १९७८ दिएका छन्।","ten":"Communist Party of Nepal (Marxist–Leninist) founded","tne":"नेकपा (मा